(function(){
  try {
    // Find the Previous button
    var prevBtn = document.querySelector('button[aria-label="Previous"]');
    if (!prevBtn) return 'No prev button found';
    // Click it 15 times with small delays
    var count = 0;
    var interval = setInterval(function(){
      prevBtn.click();
      count++;
      if (count >= 15) {
        clearInterval(interval);
      }
    }, 100);
    return 'Clicking prev 15 times';
  } catch(e) { return 'Error: ' + e.message; }
})()

(function(){
  try {
    // Find the departure input field
    var inputs = document.querySelectorAll('input[aria-label="Departure"]');
    if (inputs.length === 0) return 'No departure input found';
    var input = inputs[0];

    // Focus the input
    input.focus();

    // Set value using native input value setter
    var nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    nativeInputValueSetter.call(input, 'Mar 8, 2025');

    // Trigger events
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));

    return 'Set value to: ' + input.value;
  } catch(e) {
    return 'Error: ' + e.message;
  }
})();
